class Solution:
    def findItinerary(self, tickets):
        adj = {}
        for f, t in tickets:
            adj.setdefault(f, []).append(t)
        for k in adj:
            adj[k].sort()
        n = len(tickets)
        path = ["JFK"]

        def dfs(cur):
            if len(path) == n + 1:
                return True
            if cur not in adj:
                return False
            dests = adj[cur]
            for i in range(len(dests)):
                nxt = dests.pop(i)
                path.append(nxt)
                if dfs(nxt):
                    return True
                path.pop()
                dests.insert(i, nxt)
            return False

        dfs("JFK")
        return path

