class Solution {
public:
    vector<string> findItinerary(vector<vector<string>>& tickets) {
        unordered_map<string, deque<string>> adj;
        for (auto& t : tickets) adj[t[0]].push_back(t[1]);
        for (auto& p : adj) {
            auto& d = p.second;
            sort(d.begin(), d.end());
        }
        int n = tickets.size();
        vector<string> path{"JFK"};

        function<bool(const string&)> dfs = [&](const string& cur) {
            if ((int)path.size() == n + 1) return true;
            auto it = adj.find(cur);
            if (it == adj.end()) return false;
            auto& dests = it->second;
            for (int i = 0; i < (int)dests.size(); ++i) {
                string nxt = dests[i];
                dests.erase(dests.begin() + i);
                path.push_back(nxt);
                if (dfs(nxt)) return true;
                path.pop_back();
                dests.insert(dests.begin() + i, nxt);
            }
            return false;
        };
        dfs("JFK");
        return path;
    }
};

