class Solution {
    private Map<String, List<String>> adj = new HashMap<>();
    private List<String> path = new ArrayList<>();
    private int n;

    public List<String> findItinerary(List<List<String>> tickets) {
        n = tickets.size();
        for (List<String> t : tickets)
            adj.computeIfAbsent(t.get(0), k -> new ArrayList<>()).add(t.get(1));
        for (List<String> l : adj.values()) Collections.sort(l);
        path.add("JFK");
        dfs("JFK");
        return path;
    }

    private boolean dfs(String cur) {
        if (path.size() == n + 1) return true;
        List<String> dests = adj.get(cur);
        if (dests == null) return false;
        for (int i = 0; i < dests.size(); i++) {
            String nxt = dests.remove(i);
            path.add(nxt);
            if (dfs(nxt)) return true;
            path.remove(path.size() - 1);
            dests.add(i, nxt);
        }
        return false;
    }
}

