        if (!adj[f]) adj[f] = [];
        adj[f].push(t);
    }
    for (const k in adj) adj[k].sort();
    const n = tickets.length;
    const path = ["JFK"];

    function dfs(cur) {
        if (path.length === n + 1) return true;
        const dests = adj[cur];
        if (!dests) return false;
        for (let i = 0; i < dests.length; i++) {
            const nxt = dests.splice(i, 1)[0];
            path.push(nxt);
            if (dfs(nxt)) return true;
            path.pop();
            dests.splice(i, 0, nxt);
        }
        return false;
    }
    dfs("JFK");
    return path;
};

