import heapq
from collections import defaultdict

class Solution:
    def findItinerary(self, tickets):
        adj = defaultdict(list)
        for f, t in tickets:
            heapq.heappush(adj[f], t)
        stack = ["JFK"]
        res = []
        while stack:
            while adj[stack[-1]]:
                stack.append(heapq.heappop(adj[stack[-1]]))
            res.append(stack.pop())
        return res[::-1]

