var findItinerary = function(tickets) {
    const adj = {};
    for (const [f, t] of tickets) {
        if (!adj[f]) adj[f] = [];
        adj[f].push(t);
    }
    for (const k in adj) adj[k].sort((a, b) => b.localeCompare(a));
    const stack = ["JFK"], res = [];
    while (stack.length) {
        const top = stack[stack.length - 1];
        if (adj[top] && adj[top].length) {
            stack.push(adj[top].pop());
        } else {
            res.push(stack.pop());
        }
    }
    return res.reverse();
};
